mapper.update:
UPDATE `user`
SET status = #{toStatus},
token_version = IFNULL(token_version, 0) + 1,
updated_at = CURRENT_TIMESTAMP
WHERE id = #{userId}
AND status = #{fromStatus}

mapper.select:
select exists (
select 1 from user where email = #{email}
)

select exists (
select 1 from user where phone = #{phone}
)
